def size_text(size: int) -> str:
    if size <= 0:
        return "0 bytes"
    return f"{size} bytes ({math.ceil(size / 1024)} KiB)"


def plural(value: int, singular: str, plural_name: str | None = None) -> str:
    return singular if value == 1 else (plural_name or f"{singular}s")


def scan_summary(files: int, total_size: int, folders: int = 0) -> str:
    parts: list[str] = []
    if folders:
        parts.append(f"{folders} {plural(folders, 'folder')}")
    parts.append(f"{files} {plural(files, 'file')}")
    parts.append(size_text(total_size))
    return ", ".join(parts)


def listing_summary(files: int, total_size: int, packed_size: int, folders: int = 0) -> str:
    suffix = f"{files} files"
    if folders:
        suffix += f", {folders} folders"
    return f"{total_size:>36} {packed_size:>12}  {suffix}"


def to_display_time(mtime_ns: int | None) -> tuple[str, str]:
    if mtime_ns is None:
        return (" " * 10, " " * 8)
    dt = datetime.fromtimestamp(mtime_ns / 1_000_000_000, tz=timezone.utc)
    return dt.strftime("%Y-%m-%d"), dt.strftime("%H:%M:%S")


def to_technical_time(mtime_ns: int | None) -> str:
    if mtime_ns is None:
        return ""
    sec = mtime_ns // 1_000_000_000
    frac = mtime_ns % 1_000_000_000
    dt = datetime.fromtimestamp(sec, tz=timezone.utc)
    digits = f"{frac:09d}".rstrip("0")
    if digits:
        return f"{dt.strftime('%Y-%m-%d %H:%M:%S')}.{digits}"
    return dt.strftime("%Y-%m-%d %H:%M:%S")


def mode_string(mode: int, is_dir: bool) -> str:
    kind = stat.S_IFDIR if is_dir else stat.S_IFREG
    actual = mode or (kind | (0o755 if is_dir else 0o644))
    if stat.S_IFMT(actual) == 0:
        actual |= kind
    return stat.filemode(actual)


def attr_string(member: ArchiveMember, archive_type: str) -> str:
    if member.is_dir:
        return "D...."
    if archive_type == "7z":
        return "....A"
    return "....."


def technical_attr_string(member: ArchiveMember) -> str:
    prefix = "D" if member.is_dir else "A"
    return f"{prefix} {mode_string(member.mode, member.is_dir)}"


def normalized_name(name: str) -> str:
    return name.replace("\\", "/").rstrip("/") if name not in {"", "/"} else name


def normalize_type(type_name: str | None) -> str | None:
    if type_name is None:
        return None
    return TYPE_ALIASES.get(type_name.lower())


def append_default_extension(path: str, archive_type: str) -> str:
    suffix = Path(path).suffix
    if suffix:
        return path
    return path + TYPE_EXTENSIONS[archive_type]


def detect_type(path: str, forced_type: str | None = None) -> str | None:
    if forced_type:
        return forced_type
    suffix = Path(path).suffix.lower()
    if suffix in {".7z"}:
        return "7z"
    if suffix in {".zip"}:
        return "zip"
    if suffix in {".tar"}:
        return "tar"
    if suffix in {".gz", ".gzip"}:
        return "gzip"
    if suffix in {".bz2", ".bzip2"}:
        return "bzip2"
    if suffix in {".xz"}:
        return "xz"
    try:
        with open(path, "rb") as handle:
            header = handle.read(512)
            if header.startswith(b"7z\xbc\xaf'\x1c"):
                return "7z"
            if header.startswith((b"PK\x03\x04", b"PK\x05\x06", b"PK\x06\x06", b"PK\x07\x08")):
                return "zip"
            if header.startswith(b"\x1f\x8b\x08"):
                return "gzip"
            if header.startswith(b"BZh"):
                return "bzip2"
            if header.startswith(b"\xfd7zXZ\x00"):
                return "xz"
            if len(header) >= 265 and header[257:262] == b"ustar":
                return "tar"
    except OSError:
        return None
    return None


def read_listfile(path: str) -> list[str]:
    with open(path, "r", encoding="utf-8", errors="replace") as handle:
        return [line.rstrip("\r\n") for line in handle if line.rstrip("\r\n")]


def expand_sources(items: list[str]) -> list[str]:
    expanded: list[str] = []
    for item in items:
        if any(ch in item for ch in "*?[]"):
            matches = sorted(glob.glob(item, recursive=True))
            if matches:
                expanded.extend(matches)
            else:
                expanded.append(item)
        else:
            expanded.append(item)
    return expanded


def file_warning(path: str) -> WarningInfo:
    return WarningInfo(path=path, errno=2, message="errno=2 : No such file or directory")


def file_member_from_disk(path: str, arcname: str) -> ArchiveMember:
    st = os.stat(path)
    with open(path, "rb") as handle:
        data = handle.read()
    return ArchiveMember(
        name=normalized_name(arcname),
        is_dir=False,
        size=len(data),
        packed_size=None,
        mtime_ns=st.st_mtime_ns,
        mode=stat.S_IFREG | stat.S_IMODE(st.st_mode),
        data=data,
    )


def dir_member_from_disk(path: str, arcname: str) -> ArchiveMember:
    st = os.stat(path)
    return ArchiveMember(
        name=normalized_name(arcname),
        is_dir=True,
        size=0,
        packed_size=0,
        mtime_ns=st.st_mtime_ns,
        mode=stat.S_IFDIR | stat.S_IMODE(st.st_mode),
        data=b"",
    )


def scan_input_paths(paths: list[str]) -> ScanResult:
    result = ScanResult()
    seen: set[str] = set()
    for item in expand_sources(paths):
        if not os.path.exists(item):
            result.warnings.append(file_warning(item))
            continue
        normalized = os.path.normpath(item)
        if os.path.isdir(item):
            parent = os.path.dirname(normalized)
            root_name = os.path.basename(normalized)
            root_arc = normalized_name(root_name)
            if root_arc not in seen:
                result.entries.append(dir_member_from_disk(item, root_arc))
                result.folders += 1
                seen.add(root_arc)
            for dirpath, dirnames, filenames in os.walk(item, followlinks=True):
                dirnames.sort()
                filenames.sort()
                rel = os.path.relpath(dirpath, parent)
                rel_arc = normalized_name(rel)
                if rel_arc != root_arc and rel_arc not in seen:
                    result.entries.append(dir_member_from_disk(dirpath, rel_arc))
                    result.folders += 1
                    seen.add(rel_arc)
                for filename in filenames:
                    file_path = os.path.join(dirpath, filename)
                    rel_file = normalized_name(os.path.relpath(file_path, parent))
                    if rel_file in seen:
                        continue
                    member = file_member_from_disk(file_path, rel_file)
                    result.entries.append(member)
                    result.files += 1
                    result.total_size += member.size
                    seen.add(rel_file)
        else:
            arcname = normalized_name(os.path.basename(normalized))
            if arcname in seen:
                continue
            member = file_member_from_disk(item, arcname)
            result.entries.append(member)
            result.files += 1
            result.total_size += member.size
            seen.add(arcname)
    return result


def stdin_member(stdin_name: str | None, archive_name: str) -> ArchiveMember:
    data = sys.stdin.buffer.read()
    if stdin_name:
        name = stdin_name
    else:
        name = Path(archive_name).name
        suffix = Path(name).suffix
        if suffix:
            name = name[: -len(suffix)]
    now = time.time_ns()
    return ArchiveMember(
        name=normalized_name(name or "stdin"),
        is_dir=False,
        size=len(data),
        packed_size=None,
        mtime_ns=now,
        mode=stat.S_IFREG | 0o644,
        data=data,
    )


def load_7z(path: str) -> ArchiveModel:
    raw = read_7z_archive(path)
    members = [
        ArchiveMember(
            name=normalized_name(item.name),
            is_dir=item.is_dir,
            size=item.size,
            packed_size=0 if item.is_dir else None,
            mtime_ns=item.mtime_ns,
            mode=item.mode,
            data=item.data,
            encrypted=item.encrypted,
            method="LZMA2:12" if not item.is_dir else "",
            block=item.block,
        )
        for item in raw.entries
    ]
    file_members = [item for item in members if not item.is_dir]
    packed_total = max(0, raw.physical_size - raw.headers_size)
    if len(file_members) == 1:
        file_members[0].packed_size = packed_total
        file_members[0].block = 0
    elif len(file_members) > 1:
        file_members[0].packed_size = packed_total
        file_members[0].block = 0
        for item in file_members[1:]:
            item.packed_size = 0
            item.block = 0
    file_count = len(file_members)
    blocks = 1 if file_count else 0
    solid = file_count > 1
    return ArchiveModel(
        path=path,
        type="7z",
        physical_size=raw.physical_size,
        members=members,
        headers_size=raw.headers_size,
        method="LZMA2:12" if file_count else None,
        solid=solid,
        blocks=blocks,
    )


def load_zip(path: str) -> ArchiveModel:
    members: list[ArchiveMember] = []
    with zipfile.ZipFile(path, "r") as archive:
        for info in archive.infolist():
            is_dir = info.is_dir()
            name = normalized_name(info.filename[:-1] if is_dir and info.filename.endswith("/") else info.filename)
            mode = (info.external_attr >> 16) & 0xFFFF
            if not mode:
                mode = (stat.S_IFDIR | 0o755) if is_dir else (stat.S_IFREG | 0o644)
            dt = datetime(*info.date_time, tzinfo=timezone.utc)
            members.append(
                ArchiveMember(
                    name=name,
                    is_dir=is_dir,
                    size=info.file_size,
                    packed_size=0 if is_dir else info.compress_size,
                    mtime_ns=int(dt.timestamp() * 1_000_000_000),
                    mode=mode,
                    data=b"" if is_dir else archive.read(info),
                    encrypted=bool(info.flag_bits & 0x1),
                    method={zipfile.ZIP_STORED: "Copy", zipfile.ZIP_DEFLATED: "Deflate"}.get(info.compress_type, ""),
                )
            )
    return ArchiveModel(
        path=path,
        type="zip",
        physical_size=os.path.getsize(path),
        members=members,
    )


def tar_packed_size(size: int) -> int:
    return ((size + 511) // 512) * 512 if size else 0


def load_tar(path: str) -> ArchiveModel:
    members: list[ArchiveMember] = []
    with tarfile.open(path, "r:") as archive:
        for info in archive.getmembers():
            is_dir = info.isdir()
            name = normalized_name(info.name)
            data = b""
            if info.isfile():
                handle = archive.extractfile(info)
                data = handle.read() if handle is not None else b""
            mode = (stat.S_IFDIR | info.mode) if is_dir else (stat.S_IFREG | info.mode)
            members.append(
                ArchiveMember(
                    name=name,
                    is_dir=is_dir,
                    size=info.size,
                    packed_size=0 if is_dir else tar_packed_size(info.size),
                    mtime_ns=int(info.mtime * 1_000_000_000),
                    mode=mode,
                    data=data,
                    method="",
                )
            )
    physical_size = os.path.getsize(path)
    packed_total = sum(member.packed_size or 0 for member in members)
    return ArchiveModel(
        path=path,
        type="tar",
        physical_size=physical_size,
        members=members,
        headers_size=max(0, physical_size - packed_total),
        code_page="UTF-8",
        characteristics="GNU ASCII",
    )


def parse_gzip_header(path: str) -> tuple[str | None, int | None, int]:
    with open(path, "rb") as handle:
        raw = handle.read()

        raw = handle.read()
    if len(raw) < 10 or raw[:3] != b"\x1f\x8b\x08":
        return None, None, 0
    flags = raw[3]
    mtime = struct.unpack_from("<I", raw, 4)[0]
    index = 10
    if flags & 0x04:
        extra_len = struct.unpack_from("<H", raw, index)[0]
        index += 2 + extra_len
    name = None
    if flags & 0x08:
        end = raw.index(b"\x00", index)
        name = raw[index:end].decode("utf-8", "replace")
        index = end + 1
    if flags & 0x10:
        end = raw.index(b"\x00", index)
        index = end + 1
    if flags & 0x02:
        index += 2
    return name, (mtime or None), index


def load_raw(path: str, archive_type: str) -> ArchiveModel:
    physical_size = os.path.getsize(path)
    if archive_type == "gzip":
        with gzip.open(path, "rb") as handle:
            data = handle.read()
        header_name, mtime, header_size = parse_gzip_header(path)
        name = header_name or Path(path).with_suffix("").name
        mtime_ns = int(mtime * 1_000_000_000) if mtime else None
        return ArchiveModel(
            path=path,
            type="gzip",
            physical_size=physical_size,
            members=[
                ArchiveMember(
                    name=name,
                    is_dir=False,
                    size=len(data),
                    packed_size=physical_size,
                    mtime_ns=mtime_ns,
                    mode=stat.S_IFREG | 0o644,
                    data=data,
                )
            ],
            headers_size=header_size,
        )
    if archive_type == "bzip2":
        with bz2.open(path, "rb") as handle:
            data = handle.read()
        return ArchiveModel(
            path=path,
            type="bzip2",
            physical_size=physical_size,
            members=[
                ArchiveMember(
                    name=Path(path).with_suffix("").name,
                    is_dir=False,
                    size=len(data),
                    packed_size=physical_size,
                    mtime_ns=None,
                    mode=stat.S_IFREG | 0o644,
                    data=data,
                )
            ],
        )
    with lzma.open(path, "rb") as handle:
        data = handle.read()
    return ArchiveModel(
        path=path,
        type="xz",
        physical_size=physical_size,
        members=[
            ArchiveMember(
                name=Path(path).with_suffix("").name,
                is_dir=False,
                size=len(data),
                packed_size=physical_size,
                mtime_ns=None,
                mode=stat.S_IFREG | 0o644,
                data=data,
                method="LZMA2:12 CRC32",
            )
        ],
        method="LZMA2:12 CRC32",
        streams=1,
        blocks=1,
    )


def load_archive(path: str, forced_type: str | None = None, show_banner_on_error: bool = False) -> ArchiveModel:
    archive_type = detect_type(path, forced_type)
    if archive_type is None:
        fail_system("Can not open the file as archive", path, show_banner=show_banner_on_error)
    try:
        if archive_type == "7z":
            return load_7z(path)
        if archive_type == "zip":
            return load_zip(path)
        if archive_type == "tar":
            return load_tar(path)
        return load_raw(path, archive_type)
    except FileNotFoundError:
        fail_system("errno=2 : No such file or directory", path, show_banner=show_banner_on_error)
    except (zipfile.BadZipFile, tarfile.TarError, OSError, EOFError, SevenZipError) as exc:
        fail_system(str(exc), path, show_banner=show_banner_on_error)
    raise AssertionError("unreachable")


def write_7z(path: str, members: list[ArchiveMember]) -> None:
    entries = [
        SevenZipEntry(
            name=member.name,
            is_dir=member.is_dir,
            size=member.size,
            packed_size=0,
            mode=member.mode,
            mtime_ns=member.mtime_ns,
            data=member.data,
            encrypted=member.encrypted,
            block=None,
        )
        for member in members
    ]
    write_7z_archive(path, entries)


def write_zip(path: str, members: list[ArchiveMember], compression_level: int | None) -> None:
    compresslevel = None if compression_level is None else max(0, min(9, compression_level))
    with zipfile.ZipFile(path, "w", compression=zipfile.ZIP_DEFLATED, compresslevel=compresslevel) as archive:
        for member in members:
            name = member.name + ("/" if member.is_dir else "")
            info = zipfile.ZipInfo(name)
            if member.mtime_ns is not None:
                dt = datetime.fromtimestamp(member.mtime_ns / 1_000_000_000, tz=timezone.utc)
            else:
                dt = datetime.now(tz=timezone.utc)
            info.date_time = (dt.year, dt.month, dt.day, dt.hour, dt.minute, dt.second)
            info.compress_type = zipfile.ZIP_STORED if member.is_dir else zipfile.ZIP_DEFLATED
            info.external_attr = ((member.mode or ((stat.S_IFDIR | 0o755) if member.is_dir else (stat.S_IFREG | 0o644))) & 0xFFFF) << 16
            archive.writestr(info, b"" if member.is_dir else member.data)


def write_tar(path: str, members: list[ArchiveMember]) -> None:
    with tarfile.open(path, "w", format=tarfile.GNU_FORMAT) as archive:
        for member in members:
            info = tarfile.TarInfo(member.name)
            if member.is_dir:
                info.type = tarfile.DIRTYPE
                info.mode = stat.S_IMODE(member.mode) or 0o755
                info.size = 0
            else:
                info.type = tarfile.REGTYPE
                info.mode = stat.S_IMODE(member.mode) or 0o644
                info.size = len(member.data)
            info.mtime = (member.mtime_ns or time.time_ns()) / 1_000_000_000
            archive.addfile(info, io.BytesIO(member.data) if not member.is_dir else None)


def write_raw(path: str, archive_type: str, members: list[ArchiveMember]) -> None:
    files = [member for member in members if not member.is_dir]
    if len(files) != 1 or len(members) != 1:
        fail_system("E_INVALIDARG : One or more arguments are invalid", show_banner=False)
    member = files[0]
    if archive_type == "gzip":
        with open(path, "wb") as raw:
            with gzip.GzipFile(
                filename=member.name,
                mode="wb",
                fileobj=raw,
                mtime=(member.mtime_ns or time.time_ns()) // 1_000_000_000,
            ) as handle:
                handle.write(member.data)
        return
    if archive_type == "bzip2":
        with bz2.open(path, "wb") as handle:
            handle.write(member.data)
        return
    with lzma.open(path, "wb", format=lzma.FORMAT_XZ) as handle:
        handle.write(member.data)


def write_archive(path: str, archive_type: str, members: list[ArchiveMember], compression_level: int | None) -> None:
    if archive_type == "7z":
        write_7z(path, members)
        return
    if archive_type == "zip":
        write_zip(path, members, compression_level)
        return
    if archive_type == "tar":
        write_tar(path, members)
        return
    write_raw(path, archive_type, members)


def archive_overview(model: ArchiveModel) -> list[str]:
    lines = ["--", f"Path = {model.path}", f"Type = {model.type}"]
    if model.type != "gzip":
        lines.append(f"Physical Size = {model.physical_size}")
    if model.headers_size is not None:
        lines.append(f"Headers Size = {model.headers_size}")
    if model.method:
        lines.append(f"Method = {model.method}")
    if model.solid is not None:
        lines.append(f"Solid = {'+' if model.solid else '-'}")
    if model.blocks is not None:
        lines.append(f"Blocks = {model.blocks}")
    if model.code_page:
        lines.append(f"Code Page = {model.code_page}")
    if model.characteristics:
        lines.append(f"Characteristics = {model.characteristics}")
    if model.streams is not None:
        lines.append(f"Streams = {model.streams}")
    return lines


def print_archive_overview(model: ArchiveModel) -> None:
    for line in archive_overview(model):
        sys.stdout.write(f"{line}\n")


def match_member(name: str, patterns: list[str]) -> bool:
    if not patterns:
        return True
    base = name
    for pattern in patterns:
        if fnmatch.fnmatchcase(base, pattern):
            return True
        if fnmatch.fnmatchcase(Path(base).name, pattern):
            return True
    return False


def print_list(model: ArchiveModel, patterns: list[str], technical: bool) -> None:
    selected = [member for member in model.members if match_member(member.name, patterns)]
    if technical:
        for member in selected:
            sys.stdout.write("----------\n")
            sys.stdout.write(f"Path = {member.name}\n")
            sys.stdout.write(f"Size = {member.size}\n")
            sys.stdout.write(f"Packed Size = {'' if member.packed_size is None else member.packed_size}\n")
            sys.stdout.write(f"Modified = {to_technical_time(member.mtime_ns)}\n")
            sys.stdout.write(f"Attributes = {technical_attr_string(member)}\n")
            crc = "" if member.is_dir else f"{zlib.crc32(member.data) & 0xFFFFFFFF:08X}"
            sys.stdout.write(f"CRC = {crc}\n")
            sys.stdout.write(f"Encrypted = {'+' if member.encrypted else '-'}\n")
            sys.stdout.write(f"Method = {member.method or ''}\n")
            sys.stdout.write(f"Block = {'' if member.block is None else member.block}\n\n")
        return

    sys.stdout.write("\n")
    sys.stdout.write("   Date      Time    Attr         Size   Compressed  Name\n")
    sys.stdout.write("------------------- ----- ------------ ------------  ------------------------\n")
    total_size = 0
    total_packed = 0
    file_count = 0
    folder_count = 0
    latest = None
    for member in selected:
        date, clock = to_display_time(member.mtime_ns)
        attr = attr_string(member, model.type)
        packed = ""
        if member.is_dir:
            packed = "0"
        elif member.packed_size is not None and (member.packed_size > 0 or model.type != "7z"):
            packed = str(member.packed_size)
        sys.stdout.write(f"{date} {clock} {attr:>5} {member.size:>12} {packed:>12}  {member.name}\n")
        total_size += member.size
        if member.packed_size:
            total_packed += member.packed_size
        if member.is_dir:
            folder_count += 1
        else:
            file_count += 1
        if member.mtime_ns is not None:
            latest = max(latest or member.mtime_ns, member.mtime_ns)
    sys.stdout.write("------------------- ----- ------------ ------------  ------------------------\n")
    if latest is not None:
        date, clock = to_display_time(latest)
        sys.stdout.write(f"{date} {clock} {listing_summary(file_count, total_size, total_packed, folder_count)}\n")
    else:
        sys.stdout.write(f"{listing_summary(file_count, total_size, total_packed, folder_count)}\n")


def ensure_parent(path: Path) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)


def prompt_overwrite(target: Path, member_name: str) -> str:
    sys.stdout.write(
        "Would you like to replace the existing file:\n"
        f"  {target}\n"
        "with the file from archive:\n"
        f"  {member_name}\n"
        "? (Y)es / (N)o / (A)lways / (S)kip all / A(u)to rename all / (Q)uit? "
    )
    sys.stdout.flush()
    answer = sys.stdin.readline()
    if not answer:
        raise ExitSignal(255)
    return answer.strip().lower()[:1]


def auto_rename_path(path: Path) -> Path:
    stem = path.stem
    suffix = path.suffix
    index = 1
    while True:
        candidate = path.with_name(f"{stem}_{index}{suffix}")
        if not candidate.exists():
            return candidate
        index += 1


def extract_members(model: ArchiveModel, mode: str, output_dir: str | None, patterns: list[str], assume_yes: bool, write_stdout: bool) -> None:
