def to_display_time(mtime_ns: int | None) -> tuple[str, str]:
    if mtime_ns is None:
        return (" " * 10, " " * 8)
    dt = datetime.fromtimestamp(mtime_ns / 1_000_000_000, tz=timezone.utc)
    return dt.strftime("%Y-%m-%d"), dt.strftime("%H:%M:%S")


def to_technical_time(mtime_ns: int | None) -> str:
    if mtime_ns is None:
        return ""
    sec = mtime_ns // 1_000_000_000
    frac = mtime_ns % 1_000_000_000
    dt = datetime.fromtimestamp(sec, tz=timezone.utc)
    digits = f"{frac:09d}".rstrip("0")
    if digits:
        return f"{dt.strftime('%Y-%m-%d %H:%M:%S')}.{digits}"
    return dt.strftime("%Y-%m-%d %H:%M:%S")


